 *    ticket that land within this window of an already-sent email do not
 *    each get their own email. `maybeSendTicketReplyEmail` (called inline,
 *    right after a staff TicketMessage is written) sends immediately when
 *    the ticket has been quiet — the common case, zero added latency. When
 *    it's NOT quiet (we're inside another send's window), it does nothing
 *    and leaves the burst for `worker/ticket-reply-digest.ts`'s periodic
 *    sweep to flush as ONE email once the burst goes quiet — bounded delay,
 *    nothing silently dropped. Real support replies are normally minutes to
 *    hours apart, so this never delays a normal conversation; it only
 *    collapses genuine rapid-fire bursts (human or bug).
 *
 * 2. DAILY CAP (`TICKET_REPLY_DAILY_CAP`) — a hard circuit breaker,
 *    independent of the coalescing above. If a single customer would cross
 *    this many ticket_reply emails in a rolling 24h window, further sends
 *    stop automatically and staff get an admin Notification instead of the
 *    customer getting another email — a backstop against ANY future bug
 *    shaped like this one, not just today's specific cause. Deliberately NOT
 *    a flat "once per day" limit — a real multi-touch ticket (status update,
 *    then "fixed" a few hours later) must not get throttled into a bad
 *    support experience; the cap only bites at genuinely abnormal volume.
 *
 * Neither safeguard touches the TicketMessage write, the in-app bell
 * notification, or the Discord mirror — those still fire on every reply.
 * Only the outbound customer email is governed here.
 */

/** Staff replies to the same ticket inside this window of an already-sent
 *  email collapse into a single follow-up email instead of one each. */
export const TICKET_REPLY_COALESCE_MS = 2 * 60_000;

/** Circuit breaker: max ticket_reply emails one customer may receive in a
 *  rolling 24h window before further ones are suppressed and flagged. */
export const TICKET_REPLY_DAILY_CAP = 5;

const DAILY_WINDOW_MS = 24 * 3600_000;

/** The subject tag `emails.ticketReply` stamps on every send — used to scope
 *  EmailLog lookups to THIS ticket without a schema change. */
export function ticketReplyEmailTag(ticketId: string): string {
  return `[#${ticketId}]`;
}

/** How many ticket_reply emails has this customer been sent in the last 24h? */
export async function ticketReplyDailyCount(customerUserId: string, now: Date = new Date()): Promise<number> {
  return db.emailLog.count({
    where: {
      userId: customerUserId,
      template: "ticket_reply",
      status: "SENT",
      createdAt: { gte: new Date(now.getTime() - DAILY_WINDOW_MS) },
    },
  });
}

/** Most recent SENT ticket_reply email for this exact ticket, if any. */
async function lastSentTicketReplyEmail(ticketId: string, customerUserId: string): Promise<{ createdAt: Date } | null> {
  return db.emailLog.findFirst({
    where: {
      userId: customerUserId,
      template: "ticket_reply",
      status: "SENT",
      subject: { startsWith: ticketReplyEmailTag(ticketId) },
    },
    orderBy: { createdAt: "desc" },
    select: { createdAt: true },
  });
}

/**
 * Flag the daily cap having been reached for staff attention. Deduped to at
 * most one admin Notification per ticket per hour so a still-active
 * conversation past the cap doesn't spam the admin bell on every further
 * reply attempt.
 */
export async function flagTicketReplyDailyCapReached(ticketId: string, ticketSubject: string): Promise<void> {
  const dedupeSince = new Date(Date.now() - 60 * 60_000);
  const href = `/admin/support/${ticketId}`;
  const already = await db.notification.findFirst({
    where: { href, title: { startsWith: "⚠️ Ticket reply emails paused" }, createdAt: { gte: dedupeSince } },
  });
  if (already) return;
  console.warn(
    `[support] ticket-reply daily email cap (${TICKET_REPLY_DAILY_CAP}/24h) reached for ticket ${ticketId} — further customer emails suppressed until it rolls off`,
  );
  const admins = await db.user.findMany({ where: { role: "ADMIN" }, select: { id: true } });
  if (admins.length === 0) return;
  await db.notification.createMany({
    data: admins.map((a) => ({
      userId: a.id,
      title: `⚠️ Ticket reply emails paused (daily cap reached): ${ticketSubject}`,
      href,
    })),
  });
}

/** Actually render + send the customer-facing "ticket reply" email. No
 *  governance here — callers (the fast path below, and the digest sweep)
 *  are responsible for deciding it's OK to send. */
export async function sendTicketReplyEmailNow(
  ticketId: string,
  customerUserId: string,
  customerEmail: string,
  ticketSubject: string,
  replyPreview: string,
): Promise<void> {
  const tpl = emails.ticketReply({ ticketId, subject: ticketSubject, replyPreview });
  await sendMail({
    to: customerEmail,
    subject: tpl.subject,
    html: tpl.html,
    template: tpl.template,
    userId: customerUserId,
    kind: "support_reply",
  });
}

/**
 * Called synchronously right after a staff TicketMessage is written
 * (`lib/reply-core.ts`'s `writeTicketReply`). Fast path for the normal case;
 * defers to `worker/ticket-reply-digest.ts`'s sweep when we're mid-burst.
 * Never throws — a mail failure or governance skip must never fail the reply
 * itself; callers still wrap this in their own try/catch as defense in depth.
 */
export async function maybeSendTicketReplyEmail(args: {
  ticketId: string;
  ticketUserId: string;
  ticketSubject: string;
  replyBody: string;
}): Promise<void> {
  const sentToday = await ticketReplyDailyCount(args.ticketUserId);
  if (sentToday >= TICKET_REPLY_DAILY_CAP) {
    await flagTicketReplyDailyCapReached(args.ticketId, args.ticketSubject);
    return;
  }

  const lastSent = await lastSentTicketReplyEmail(args.ticketId, args.ticketUserId);
  if (lastSent && Date.now() - lastSent.createdAt.getTime() < TICKET_REPLY_COALESCE_MS) {
    // Inside another send's coalesce window — leave this burst for the
    // digest sweep to flush as one email once it goes quiet.
    console.info("[support] staff-reply email deferred to digest sweep (coalesce window)", args.ticketId);
    return;
  }

  const customer = await db.user.findUnique({ where: { id: args.ticketUserId }, select: { email: true } });
  if (!customer?.email) return;
  await sendTicketReplyEmailNow(args.ticketId, args.ticketUserId, customer.email, args.ticketSubject, args.replyBody);
}

