// Ticket-reply email digest sweep (worker task).
//
// Registered on the worker loop (worker/index.ts). Flushes the "one email per
// burst" side of `lib/ticket-reply-email.ts`'s coalescing safeguard — see that
// file's top-of-file comment for the full incident writeup and design.
//
// `maybeSendTicketReplyEmail` (called inline from `lib/reply-core.ts` right
// after a staff reply is written) sends immediately when a ticket has been
// quiet for a while (the common case). When a new staff reply lands inside
// another send's `TICKET_REPLY_COALESCE_MS` window, it deliberately does
// NOTHING — no email goes out for that reply. This sweep is what guarantees
// that burst still gets exactly ONE follow-up email once it goes quiet,
// instead of the customer's latest update just silently never being mailed.
//
// FINDING CANDIDATES WITHOUT A SCHEMA CHANGE: there is no "pending digest"
// column anywhere. Instead this derives pending state from data that already
// exists — any ticket with a staff-authored TicketMessage newer than that
// ticket's most recent SENT `ticket_reply` EmailLog row is "behind" and needs
// a catch-up email once the newest such message has been quiet long enough.
// Scoped to staff messages from the last 30 minutes: `TICKET_REPLY_COALESCE_MS`
// is only 2 minutes, so anything that could still be "pending and not yet
// quiet long enough" is always well inside that lookback; this just bounds
// the scan to recent activity instead of walking every ticket that ever
// existed. (If ticket volume grows enough for this per-tick scan to matter,
// the natural next step is a real `pendingReplyEmailSince` column — not done
// here since the current volume makes it unnecessary and this ships faster
// without a migration during an active incident.)
//
// Polled every ~20s (see worker/index.ts) — short enough that the 2-minute
// coalesce window doesn't turn into a much longer real-world delay.

import { db } from "../lib/db";
import {
  TICKET_REPLY_COALESCE_MS,
  TICKET_REPLY_DAILY_CAP,
  ticketReplyEmailTag,
  ticketReplyDailyCount,
  flagTicketReplyDailyCapReached,
  sendTicketReplyEmailNow,
} from "../lib/ticket-reply-email";

/** How far back to look for candidate tickets. Generous relative to the
 *  2-minute coalesce window so a sweep hiccup can't miss a pending burst. */
const CANDIDATE_LOOKBACK_MS = 30 * 60_000;

/** Bounded per-sweep-tick send budget — mirrors the pattern in
 *  lib/critical-email-retry.ts: a backlog can't hammer the mail relay. */
const MAX_SENDS_PER_SWEEP = 20;

/** Gentle pacing between sends within one sweep tick. */
const SEND_GAP_MS = 500;
const sleep = (ms: number) => new Promise((r) => setTimeout(r, ms));

export async function ticketReplyDigestSweep(): Promise<void> {
  const since = new Date(Date.now() - CANDIDATE_LOOKBACK_MS);

  // Distinct tickets that had a staff reply recently — candidates for "is
  // this ticket behind on its customer-facing email?".
  const recentStaffMessages = await db.ticketMessage.findMany({
    where: { isStaff: true, createdAt: { gte: since } },
    distinct: ["ticketId"],
    select: { ticketId: true },
  });
  if (recentStaffMessages.length === 0) return;

  let sent = 0;
  for (const { ticketId } of recentStaffMessages) {
    if (sent >= MAX_SENDS_PER_SWEEP) break;

    const latestStaffMessage = await db.ticketMessage.findFirst({
      where: { ticketId, isStaff: true },
      orderBy: { createdAt: "desc" },
      select: { createdAt: true, body: true },
    });
    if (!latestStaffMessage) continue;

    // Still inside the coalesce window since this ticket's newest staff
    // reply — not quiet yet, leave it for a later tick (or the inline fast
    // path may still catch it if this is actually the very first reply).
    if (Date.now() - latestStaffMessage.createdAt.getTime() < TICKET_REPLY_COALESCE_MS) continue;

    const ticket = await db.ticket.findUnique({ where: { id: ticketId }, select: { userId: true, subject: true } });
    if (!ticket) continue;

    const lastSentEmail = await db.emailLog.findFirst({
      where: {
        userId: ticket.userId,
        template: "ticket_reply",
        status: "SENT",
        subject: { startsWith: ticketReplyEmailTag(ticketId) },
      },
      orderBy: { createdAt: "desc" },
      select: { createdAt: true },
    });
    // Already caught up — the fast path already mailed this exact reply (or a
    // later one hasn't landed yet). Nothing to flush.
    if (lastSentEmail && lastSentEmail.createdAt >= latestStaffMessage.createdAt) continue;

    if ((await ticketReplyDailyCount(ticket.userId)) >= TICKET_REPLY_DAILY_CAP) {
      await flagTicketReplyDailyCapReached(ticketId, ticket.subject);
      continue;
    }

    const customer = await db.user.findUnique({ where: { id: ticket.userId }, select: { email: true } });
    if (!customer?.email) continue;

    try {
      await sendTicketReplyEmailNow(ticketId, ticket.userId, customer.email, ticket.subject, latestStaffMessage.body);
      sent++;
      await sleep(SEND_GAP_MS);
    } catch (e) {
      console.error("[ticket-reply-digest] send failed (non-fatal)", ticketId, e);
    }
  }
}

