--- final reply-core.ts sendmail section ---
import "server-only";
import { z } from "zod";
import { db } from "./db";
import { maybeSendTicketReplyEmail } from "./ticket-reply-email";

/**
 * Shared reply-writing core for support tickets and live chat, extracted from
 * lib/actions-support.ts's `replyTicket` and lib/actions-chat.ts's
 * `replyToConversation` so there is exactly ONE code path that writes a
 * reply, regardless of which surface triggers it: the existing "use server"
 * actions behind /dashboard/support and /admin/chat, or the new Discord
 * bridge webhook (app/api/webhooks/discord/route.ts).
 *
 * SECURITY — READ THIS BEFORE CALLING EITHER FUNCTION BELOW.
 *
 * Neither function performs ANY authorization check. That is deliberate, not
 * an oversight: `lib/actions-support.ts`'s own top-of-file comment documents a
 * real, previously-shipped RBAC bug in this exact reply path (a SUPPORT agent
 * could silently neither answer nor close a ticket that wasn't their own), so
 * this extraction is surgical — the DB-write body moved here VERBATIM, auth
 * stayed put. Every existing caller still does its own guard before calling
 * in:
 *   - `replyTicket` (lib/actions-support.ts) calls `requireTicketActor()` first.
 *   - `replyToConversation`/`replyWithAttachment` (lib/actions-chat.ts) call
 *     `requireArea("support")` first.
 *   - The Discord webhook route's "auth" is Discord's own Ed25519
 *     interaction-signature verification (lib/discord.ts's
 *     `verifyDiscordSignature`) PLUS `lib/discord-bridge.ts`'s
 *     `resolveDiscordReplyActor`, which resolves the real Discord user who
 *     submitted the reply (via `interaction.member.user.id`) to a Nxeon
 *     `User.discordUserId` link and re-checks that account still has support
 *     access — see that file's top-of-file comment for the full design
 *     (real per-person linking via OAuth, no fallback to a single shared
 *     identity).
 *
 * Do NOT add a new caller of `writeTicketReply`/`writeChatReply` without first
 * adding its own auth check — these functions will happily write a reply
 * attributed to whatever actorId/staffId they're given.
 */

/** Write a ticket reply. Mirrors `replyTicket`'s exact prior DB-write body. */
export async function writeTicketReply(args: {
  /** The id of the user the message is authored as (TicketMessage.authorId). */
  actorId: string;
  /** Whether the calling actor is support staff (before the same-ticket-owner override below). */
  actorIsSupportStaff: boolean;
  ticketId: string;
  body: string;
  /** Optional single attachment (image or document) — see lib/ticket-attachment.ts. */
  attachment?: { mime: string; name: string; size: number; data: Buffer };
}): Promise<{ error?: string; isStaff?: boolean; ticketUserId?: string; subject?: string }> {
  const body = args.body.trim();
  // A message with an attachment and no caption is allowed (mirrors the chat
  // widget's image-only messages), so the length floor only applies when there
  // is no attachment to carry the message on its own.
  if (!args.attachment && (body.length < 2 || body.length > 10000)) return { error: "Message too short." };
  if (body.length > 10000) return { error: "Message is too long." };

  const ticket = await db.ticket.findUnique({ where: { id: args.ticketId } });
  if (!ticket) return { error: "Ticket not found." };
  // A staff member replying to their OWN ticket (as its customer) is not a
  // "staff reply" — exactly the same override the original action applied.
  const isStaff = args.actorIsSupportStaff && ticket.userId !== args.actorId;
  if (ticket.userId !== args.actorId && !args.actorIsSupportStaff) return { error: "Forbidden." };

  await db.$transaction([
    db.ticketMessage.create({
      data: {
        ticketId: args.ticketId,
        body,
        authorId: args.actorId,
        isStaff,
        ...(args.attachment
          ? {
              attachmentData: new Uint8Array(args.attachment.data),
              attachmentMime: args.attachment.mime,
              attachmentName: args.attachment.name,
              attachmentSize: args.attachment.size,
            }
          : {}),
